const wf    = $json.workflow  || {};
const err   = $json.error     || {};
const exec  = $json.execution || {};

const wfName   = String(wf.name  || 'Unknown Workflow');
const wfId     = String(wf.id    || '');
const errMsg   = String(err.message || 'No message');
const errStack = String(err.stack   || '');
const execId   = String(exec.id     || '');
const execMode = String(exec.mode   || '');
const now      = new Date().toISOString();

const subject = '[Qoryva 告警] M1 Workflow 錯誤：' + wfName;

const html = `
<div style="font-family:monospace;font-size:14px;line-height:1.8;color:#222;">
  <h2 style="color:#c0392b;">🚨 Qoryva M1 Workflow 發生錯誤</h2>
  <table style="border-collapse:collapse;width:100%;">
    <tr><td style="padding:4px 12px 4px 0;font-weight:bold;color:#555;">Workflow</td><td>${wfName}</td></tr>
    <tr><td style="padding:4px 12px 4px 0;font-weight:bold;color:#555;">Workflow ID</td><td>${wfId}</td></tr>
    <tr><td style="padding:4px 12px 4px 0;font-weight:bold;color:#555;">Execution ID</td><td>${execId}</td></tr>
    <tr><td style="padding:4px 12px 4px 0;font-weight:bold;color:#555;">執行模式</td><td>${execMode}</td></tr>
    <tr><td style="padding:4px 12px 4px 0;font-weight:bold;color:#555;">時間</td><td>${now}</td></tr>
    <tr><td style="padding:4px 12px 4px 0;font-weight:bold;color:#555;">錯誤訊息</td><td style="color:#c0392b;">${errMsg}</td></tr>
  </table>
  <hr style="margin:16px 0;border:none;border-top:1px solid #ddd;"/>
  <p style="font-weight:bold;color:#555;">Stack Trace：</p>
  <pre style="background:#f5f5f5;padding:12px;border-radius:4px;white-space:pre-wrap;font-size:12px;">${errStack}</pre>
  <hr style="margin:16px 0;border:none;border-top:1px solid #ddd;"/>
  <p style="color:#888;font-size:12px;">Qoryva AI Operations — 自動告警</p>
</div>
`;

return [{ json: { subject, html } }];
